// Evaluate Reverse Polish Notation (RPN / Postfix)
var stack = AnimatedStack<Int>()
let tokens = ["2", "1", "+", "3", "*"]

func evaluateRPN(_ tokens: [String], s: inout AnimatedStack<Int>) -> Int {
    for token in tokens {
        if token == "+" || token == "-" || token == "*" || token == "/" {
            let b = s.pop() ?? 0
            let a = s.pop() ?? 0
            switch token {
            case "+": s.push(a + b)
            case "-": s.push(a - b)
            case "*": s.push(a * b)
            case "/": s.push(a / b)
            default: break
            }
        } else if let num = Int(token) {
            s.push(num)
        }
    }
    return s.pop() ?? 0
}

let resultVal = evaluateRPN(tokens, s: &stack)
